"""Customer dashboard; public Supabase settings only, never private credentials."""
import json,base64
from site_components import ROOT,mobile_toolbar,merchandise
from site_images import brand_mark
from site_metadata import write_html

def main():
 c=json.loads((ROOT/'data/account.json').read_text())
 key=c.get('publishable_key','')
 if key:
  if key.startswith('sb_secret_'):raise ValueError('Never publish a Supabase secret key.')
  if key.startswith('eyJ'):
   payload=json.loads(base64.urlsafe_b64decode(key.split('.')[1]+'==='))
   if payload.get('role')!='anon':raise ValueError('Only an anon/public key may be published.')
  elif not key.startswith('sb_publishable_'):raise ValueError('Use a Supabase public publishable key.')
 (ROOT/'account/config.json').write_text(json.dumps(c,indent=2)+'\n')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><meta name="description" content="Your Crystal Eye account: keep your numerology and astrology readings, save your signs, and view your tarot subscription."><title>My Account | Crystal Eye</title><link rel="stylesheet" href="../assets/site.css"><link rel="stylesheet" href="../assets/merchandise.css"><link rel="stylesheet" href="../assets/cyberpunk.css"><link rel="stylesheet" href="../assets/mobile-toolbar.css?v=3"><link rel="stylesheet" href="account.css"><script src="../assets/site.js" defer></script><script type="module" src="account.js"></script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header wrap"><a class="brand" href="../index.html">{brand_mark('../')}<span>crystaleye.</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu</button><nav id="site-nav" aria-label="Main navigation"><a href="../astrology/index.html">Astrology</a><a href="../tarot/index.html">Tarot</a><a href="../numerology/index.html">Numerology</a><a href="../merchandise/index.html">Shop</a></nav></header><main id="main"><section class="wrap account-hero"><p class="eyebrow">Your personal corner of Crystal Eye</p><h1>Your readings.<br><em>Your space.</em></h1><p class="section-copy">Keep the numbers and reflections you want to return to. Save your astrology signs and see your tarot subscription in one place.</p><p id="account-status" class="account-notice" role="status" aria-live="polite">Checking your account…</p></section><section class="wrap account-login" id="login-panel"><div class="account-panel"><h2>Come on in.</h2><p>New here? The same email link creates your account. Already a member? It signs you back in. No password to remember.</p><form id="login-form"><fieldset id="login-fields" disabled><label for="login-email">Your email address</label><input type="email" id="login-email" autocomplete="email" maxlength="254" required><button class="button button-gold" type="submit">Email me a sign-in link →</button></fieldset></form><p id="login-status" role="status" class="fine-print"></p><p class="fine-print">Open your sign-in email in this same browser. Signing in does not start a paid subscription. Your session stays signed in on this browser until you sign out.</p></div><div><h2>A little continuity.</h2><ul class="account-benefits"><li>Save your three-number numerology results.</li><li>Keep astrology reflections and your Sun, Moon, and rising signs.</li><li>Check your tarot and astrology subscription status.</li></ul><p class="fine-print">We store your email for sign-in, the profile details you choose, and readings you explicitly save. The quick calculator does not send your birth name or birth date to your account.</p></div></section><div class="wrap account-dashboard" id="dashboard" hidden><div class="account-welcome"><div><h2 id="welcome-title">Welcome back.</h2><p id="signed-in-email" class="fine-print"></p></div><button id="sign-out" class="button button-outline" type="button">Sign out</button></div><nav class="account-jumps" aria-label="Account sections"><a href="#profile">My profile</a><a href="#saved">Saved readings</a><a href="#subscriptions">My subscriptions</a></nav><section class="account-panel" id="profile"><p class="eyebrow">Make it yours</p><h2>My profile</h2><form id="profile-form"><label for="display-name">Display name</label><input id="display-name" autocomplete="nickname" maxlength="80"><div class="account-signs">{''.join(f'<div><label for="profile-{role}">{role.title()} sign</label><select id="profile-{role}"><option value="">Not sure yet</option></select></div>' for role in ['sun','moon','rising'])}</div><p class="fine-print">Choose signs you already know. We do not calculate your Moon or rising from this form. <a href="../astrology/index.html#find-your-signs">Learn how to find your signs →</a></p><button class="button button-gold" type="submit">Save profile</button><p id="profile-status" class="fine-print" role="status"></p></form><button id="save-today" class="button button-outline" type="button">Save today’s astrology reflection</button><p id="today-status" class="fine-print" role="status"></p></section><section class="account-panel" id="saved"><p class="eyebrow">Return to what resonates</p><h2>Saved readings</h2><p>Use “Save to my account” after calculating your numbers or previewing an astrology reading. Nothing is saved automatically.</p><div class="account-filters" role="group" aria-label="Filter saved readings"><button type="button" data-reading-filter="all" aria-pressed="true">All</button><button type="button" data-reading-filter="numerology" aria-pressed="false">Numerology</button><button type="button" data-reading-filter="astrology" aria-pressed="false">Astrology</button></div><p id="saved-status" role="status" class="fine-print"></p><div id="saved-readings"></div><button type="button" class="button button-outline" id="load-more" hidden>Load more readings</button><div class="account-explore"><a href="../numerology/index.html#calculator">Find your three numbers →</a><a href="../astrology/index.html#email-preview">Explore astrology →</a></div></section><section class="account-panel" id="subscriptions"><p class="eyebrow">Your daily ritual</p><h2>My subscriptions</h2><p>Subscriptions are separate from your free account. Your current plans and billing status appear here.</p><p id="subscription-status" role="status" class="fine-print"></p><div id="subscription-list" class="account-subscriptions"></div><a class="text-link" href="../merchandise/index.html#subscriptions">Explore subscription plans →</a><p class="fine-print">Subscription checkout and paid access are not activated yet. The three-card tarot spread on the site remains a clearly labeled preview.</p></section></div><noscript><p class="wrap account-notice">Enable JavaScript to sign in and manage your private account. Public guides and readings remain available.</p></noscript>{merchandise('../')}</main><footer class="site-footer wrap"><a href="../index.html">Crystal Eye home →</a><a href="../psychic-readings/index.html">Book a personal reading →</a></footer>{mobile_toolbar('../')}</body></html>'''
 write_html(ROOT/'account/index.html',html)
 print('Built customer account dashboard and public connection settings.')
if __name__=='__main__':main()
